    private String id;
    private String name;
    private int salary;
    public Employee(String id, String name) {
        this.id = id;
        this.name = name;
        this.salary = 1000;
    }
    @Override
    public void notice() {
        System.out.println("Employee salary computed!");
    }
    @Override
    public void increase() {
        this.salary += 200;
    }
